tool.command:
## NFS root_squash: root in container → nobody on NFS, can't write to galaxy-owned workdir. groupadd -g 1001 gxgroup 2>/dev/null || true && useradd -M -u 1001 -g 1001 gxuser 2>/dev/null || true && export HOME=\$PWD/home/ && export CELLPOSE_START_DIR=\$PWD/home/cp_working_dir/ && runuser -u gxuser -- bash -c "mkdir -p ./home/cp_working_dir/models/safe" && #for $i,$filename in enumerate($infiles): runuser -u gxuser -- bash -c "ln -s '$filename' './home/cp_working_dir/${filename.element_identifier}.${filename.ext}'" && #end for ## /init calls mktemp; Galaxy sets TMPDIR=$CWD/tmp/ which root_squash blocks. Reset to /tmp. export TMPDIR=/tmp && ## Reconfigure container nginx for path-based proxy: EP_PATH_CLEAN="\${EP_PATH%/}" && sed -i "s|location ~ /websockify|location \${EP_PATH_CLEAN}/websockify {
 websockify_pass unix:/tmp/vnc.sock;
 websockify_read_timeout 5d;
 websockify_send_timeout 5d;
 }

 location \${EP_PATH_CLEAN} {
 alias /opt/noVNC/;
 index index.html;
 add_header Cache-Control no-cache;
 }

 location ~ /websockify|" /opt/base/etc/nginx/default_site.conf && /init && if [ -n "\$(ls -A ./home/cp_working_dir/models 2>/dev/null)" ]; then runuser -u gxuser -- bash -c "rm -f ./home/cp_working_dir/models/*.npy && python3 '$__tool_directory__/pytorch_convert_safetensors.py' --convert pt_safe --batch -i './home/cp_working_dir/models/' -o './home/cp_working_dir/models/safe'"; fi
